long c = 10L;
float d = 1.5f;
System.out.println(c + d); // 11.5 (float)

int e = 3;
long f = 4L;
System.out.println(e + f); // 7 (long)
// Java automatycznie promuje oba operandy do SZERSZEGO z dwóch typów
// przed wykonaniem działania (binarna promocja numeryczna).

char c = 'a';
System.out.println(c + 1);        // 98 (int)
System.out.println((char) (c + 1)); // 'b'

Double d1 = 3.14;
double d2 = 3.14;
System.out.println(d1 == d2);      // true - d1 jest unboxowany do double przed porownaniem
System.out.println(d1.equals(d2)); // true - porównanie wartości

String word = "Hello";
char[] chars = word.toCharArray();
for (int i = 0; i < chars.length; i++) {
    chars[i] = (char) (chars[i] + 1);
}
String result = new String(chars);
System.out.println(result);

int n = 255;
System.out.println(Integer.toBinaryString(n));
System.out.println(Integer.toHexString(n));
System.out.println(Integer.toOctalString(n));

static class Shape {}
static class Circle extends Shape {}

// W main():
Shape s = new Circle();
System.out.println(s.getClass().getSimpleName()); // "Circle"

Shape[] shapes = {new Circle(), new Shape(), new Circle()};
for (Shape shape : shapes) {
    if (shape instanceof Circle) {
        Circle circle = (Circle) shape;
        circle.draw();
    } else {
        shape.show();
    }
}

Object[] objects = {"Hello", 42, 3.14, true, 'Z'};
for (Object obj : objects) {
    if (obj instanceof String s) {
        System.out.println("String: " + s);
    } else if (obj instanceof Integer i) {
        System.out.println("Integer: " + i);
    } else if (obj instanceof Double d) {
        System.out.println("Double: " + d);
    } else if (obj instanceof Boolean b) {
        System.out.println("Boolean: " + b);
    } else if (obj instanceof Character c) {
        System.out.println("Character: " + c);
    }
}

int a = 7, b = 2;
System.out.println(a / b);          // 3 - dzielenie całkowitoliczbowe
System.out.println((double) a / b); // 3.5 - a rzutowane na double PRZED dzieleniem
// (double) a / b: rzutowanie 'a' wymusza, by CALE działanie było zmiennoprzecinkowe.

Integer wrapped = Integer.valueOf(100);
System.out.println(wrapped.intValue());
System.out.println(wrapped.doubleValue());
System.out.println(wrapped.longValue());
System.out.println("MAX: " + Integer.MAX_VALUE);
System.out.println("MIN: " + Integer.MIN_VALUE);

String num = "127";
System.out.println(Byte.parseByte(num));
System.out.println(Short.parseShort(num));
System.out.println(Integer.parseInt(num));
System.out.println(Long.parseLong(num));
System.out.println(Float.parseFloat(num));
System.out.println(Double.parseDouble(num));

double d = 9.99;
System.out.println((int) d);        // 9 - obciecie czesci ulamkowej
System.out.println(Math.round(d));  // 10 - zaokrąglenie do najbliższej
// (int) ZAWSZE obcina (w kierunku zera), Math.round() zaokrągla do NAJBLIŻSZEJ
// liczby całkowitej - dla 9.99 dają RÓZNE wyniki.

int i = 300;
byte b = (byte) i;
System.out.println(b); // 44
// byte może przechowac tylko 256 roznych wartości (-128..127) - rzutowanie
// 'zawija' wartość modulo 256: 300 % 256 = 44 (dokładnie ta wartość widzimy).

static class Vehicle {}
static class Car extends Vehicle { void honk() { System.out.println("Beep!"); } }
static class ElectricCar extends Car { void charge() { System.out.println("Ładuje..."); } }

// W main():
Vehicle v = new ElectricCar();
System.out.println(v instanceof Vehicle);     // true
System.out.println(v instanceof Car);         // true
System.out.println(v instanceof ElectricCar); // true

if (v instanceof ElectricCar ec) {
    ec.charge();
}

Object[] mixed = {1, "two", 3.0, '4', true, 5L};
for (Object obj : mixed) {
    if (obj instanceof Number n) {
        System.out.println(n.doubleValue() + 100);
    } else if (obj instanceof String s) {
        System.out.println("Długość: " + s.length());
    } else if (obj instanceof Character c) {
        System.out.println("Kod ASCII: " + (int) c);
    } else if (obj instanceof Boolean b) {
        System.out.println("Odwrocone: " + !b);
    }
}

